CREATE TABLE maintenance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vehicle_id BIGINT UNSIGNED NOT NULL, financial_transaction_id BIGINT UNSIGNED NULL, maintenance_date DATE NOT NULL, maintenance_type ENUM('preventive','corrective','inspection','other') NOT NULL, description VARCHAR(500) NOT NULL, next_due_date DATE NULL, odometer_km DECIMAL(15,2) NULL, cost DECIMAL(15,2) NOT NULL DEFAULT 0.00, status ENUM('scheduled','in_progress','completed','cancelled') NOT NULL DEFAULT 'scheduled', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_maintenance_ft (financial_transaction_id), KEY idx_maintenance_vehicle_date (vehicle_id,maintenance_date), CONSTRAINT chk_maintenance_values CHECK (cost >= 0 AND (odometer_km IS NULL OR odometer_km >= 0)), CONSTRAINT fk_maintenance_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT, CONSTRAINT fk_maintenance_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
